$ErrorActionPreference = "Stop"

function Resolve-YkayRoot {
    param([string]$Hint)
    $candidates = @()
    if ($Hint) { $candidates += $Hint }
    if ($PSScriptRoot) { $candidates += $PSScriptRoot }
    $candidates += (Get-Location).Path
    $candidates += "C:\Users\USER\Desktop\PROJECTS\ykay_edu\envoys-site"
    foreach ($c in $candidates) {
        if (-not $c) { continue }
        try {
            $full = [System.IO.Path]::GetFullPath($c)
        } catch { continue }
        if ((Test-Path (Join-Path $full "package.json")) -and (Test-Path (Join-Path $full "prisma\schema.prisma"))) {
            return $full
        }
        # script may live in deliverables\phase6b
        $up = Split-Path $full -Parent
        if ($up -and (Test-Path (Join-Path $up "package.json")) -and (Test-Path (Join-Path $up "prisma\schema.prisma"))) { return $up }
        $up2 = if ($up) { Split-Path $up -Parent } else { $null }
        if ($up2 -and (Test-Path (Join-Path $up2 "package.json")) -and (Test-Path (Join-Path $up2 "prisma\schema.prisma"))) { return $up2 }
    }
    throw "Could not locate Ykay project root (package.json + prisma/schema.prisma). cd into the repo first."
}

$Root = Resolve-YkayRoot -Hint $PSScriptRoot
Set-Location -LiteralPath $Root
Write-Host "Project root: $Root" -ForegroundColor Cyan

if (-not (Test-Path (Join-Path $Root ".git"))) {
    Write-Host "WARNING: .git not found in root. Continuing anyway." -ForegroundColor Yellow
}

function Write-YkayFile {
    param(
        [Parameter(Mandatory = $true)][string]$RelativePath,
        [Parameter(Mandatory = $true)][byte[]]$Bytes
    )
    $full = [System.IO.Path]::GetFullPath((Join-Path $Root $RelativePath))
    $rootFull = [System.IO.Path]::GetFullPath($Root)
    if (-not $full.StartsWith($rootFull, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw "Refusing to write outside project root: $full"
    }
    $dir = Split-Path -Parent $full
    if ($dir -and -not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    [System.IO.File]::WriteAllBytes($full, $Bytes)
    Write-Host ("  wrote {0}" -f $RelativePath) -ForegroundColor DarkGray
}

# Remove broken empty migration dirs from earlier failed injects
$migRoot = Join-Path $Root "prisma\migrations"
if (Test-Path $migRoot) {
    Get-ChildItem -LiteralPath $migRoot -Directory | ForEach-Object {
        $sql = Join-Path $_.FullName "migration.sql"
        if (-not (Test-Path -LiteralPath $sql)) {
            Write-Host ("  removing empty migration dir {0}" -f $_.Name) -ForegroundColor Yellow
            Remove-Item -LiteralPath $_.FullName -Recurse -Force
        }
    }
}

Write-Host "`n─── 1/5  Extract Phase 6B source pack ─────────────────────────────" -ForegroundColor Yellow

$expectedSha = "94d10d33452af7a6fdd020a8741fd94334bd7bcd6fb232cd7fd09220fc6fdc22"
$b64 = @'

'@

$zipBytes = [Convert]::FromBase64String(($b64 -replace "\s", ""))
$shaActual = [System.BitConverter]::ToString([System.Security.Cryptography.SHA256]::Create().ComputeHash($zipBytes)).Replace("-", "").ToLowerInvariant()
if ($shaActual -ne $expectedSha) { throw "Source pack checksum mismatch. Aborting." }

$tmpZip = Join-Path $env:TEMP ("ykay-phase6b-" + [guid]::NewGuid().ToString() + ".zip")
$tmpOut = Join-Path $env:TEMP ("ykay-phase6b-" + [guid]::NewGuid().ToString())
[System.IO.File]::WriteAllBytes($tmpZip, $zipBytes)
New-Item -ItemType Directory -Path $tmpOut -Force | Out-Null
Add-Type -AssemblyName System.IO.Compression.FileSystem
[System.IO.Compression.ZipFile]::ExtractToDirectory($tmpZip, $tmpOut)

Get-ChildItem -LiteralPath $tmpOut -Recurse -File | ForEach-Object {
    $rel = $_.FullName.Substring($tmpOut.Length).TrimStart("\", "/")
    $rel = $rel -replace "/", "\"
    if ($rel -like "patches\*") { return }
    $bytes = [System.IO.File]::ReadAllBytes($_.FullName)
    Write-YkayFile -RelativePath $rel -Bytes $bytes
}

Write-Host "`n─── 2/5  Patch prisma/schema.prisma for FeePaymentAttempt ─────────" -ForegroundColor Yellow

$schemaPath = Join-Path $Root "prisma\schema.prisma"
$schema = [System.IO.File]::ReadAllText($schemaPath)

if ($schema -notmatch "model FeePaymentAttempt") {
    if ($schema -match "idempotencyRecords\s+IdempotencyRecord\[\]") {
        $schema = $schema -replace "idempotencyRecords\s+IdempotencyRecord\[\]", "idempotencyRecords      IdempotencyRecord[]`r`n  feePaymentAttempts     FeePaymentAttempt[]"
    } elseif ($schema -match "newsPosts\s+NewsPost\[\]") {
        $schema = $schema -replace "newsPosts\s+NewsPost\[\]", "newsPosts               NewsPost[]`r`n  feePaymentAttempts     FeePaymentAttempt[]"
    }

    if ($schema -match "model FeeInvoice \{") {
        $schema = [regex]::Replace($schema, "(model FeeInvoice \{[\s\S]*?payments\s+FeePayment\[\])", "`$1`r`n  paymentAttempts FeePaymentAttempt[]", 1)
    }

    if ($schema -match "examRetakes\s+ExamRetake\[\]") {
        $schema = $schema -replace "examRetakes\s+ExamRetake\[\]", "examRetakes          ExamRetake[]`r`n  feePaymentAttempts  FeePaymentAttempt[]"
    }

    if ($schema -match "model ParentProfile \{") {
        $schema = [regex]::Replace($schema, "(model ParentProfile \{[\s\S]*?feePayments\s+FeePayment\[\])", "`$1`r`n  feePaymentAttempts FeePaymentAttempt[]", 1)
    }

    $model = @"

model FeePaymentAttempt {
  id                String          @id @default(cuid())
  schoolId          String
  invoiceId         String
  studentProfileId  String
  parentProfileId   String?
  provider          PaymentProvider
  amount            Int
  reference         String          @unique
  status            PaymentStatus   @default(PENDING)
  payerEmail        String?
  transferDate      DateTime?
  transferNarration String?
  providerData      Json?
  reviewedByUserId  String?
  reviewedAt        DateTime?
  createdAt         DateTime        @default(now())
  updatedAt         DateTime        @updatedAt

  school         School         @relation(fields: [schoolId], references: [id], onDelete: Cascade)
  invoice        FeeInvoice     @relation(fields: [invoiceId], references: [id], onDelete: Cascade)
  studentProfile StudentProfile @relation(fields: [studentProfileId], references: [id], onDelete: Cascade)
  parentProfile  ParentProfile? @relation(fields: [parentProfileId], references: [id], onDelete: SetNull)

  @@index([schoolId, status, createdAt])
  @@index([invoiceId, status])
}
"@
    $schema = $schema.TrimEnd() + "`r`n" + $model + "`r`n"
    $utf8 = New-Object System.Text.UTF8Encoding $false
    [System.IO.File]::WriteAllText($schemaPath, $schema, $utf8)
    Write-Host "  schema patched with FeePaymentAttempt" -ForegroundColor DarkGray
} else {
    Write-Host "  FeePaymentAttempt already present — skipped schema patch" -ForegroundColor DarkGray
}

Write-Host "`n─── 3/5  Prisma generate + migrate deploy ─────────────────────────" -ForegroundColor Yellow
npx prisma generate
if ($LASTEXITCODE -ne 0) { throw "prisma generate failed" }
npx prisma migrate deploy
if ($LASTEXITCODE -ne 0) {
    Write-Host "migrate deploy failed — try: npx prisma migrate dev --name phase_6b_fee_payments" -ForegroundColor Red
    throw "prisma migrate deploy failed"
}

Write-Host "`n─── 4/5  Production build ─────────────────────────────────────────" -ForegroundColor Yellow
if (Test-Path (Join-Path $Root ".next")) { Remove-Item -Recurse -Force (Join-Path $Root ".next") }
npm run build
if ($LASTEXITCODE -ne 0) {
    Write-Host "Build reported errors. Review TypeScript output above." -ForegroundColor Yellow
}

Write-Host "`n─── 5/5  Cleanup temp ─────────────────────────────────────────────" -ForegroundColor Yellow
Remove-Item -LiteralPath $tmpZip -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $tmpOut -Recurse -Force -ErrorAction SilentlyContinue

